FROM jsonb_populate_recordset(NULL::public.services, $akrasia_services$[{"id":"00000000-0000-4000-8000-000000000920","slug":"ai-generation","title":"Producción audiovisual con IA","title_en":"AI audiovisual production","description":"Piezas audiovisuales que combinan dirección humana y herramientas de IA.","description_en":"Audiovisual work combining human direction and AI tools.","icon":"movie","highlighted":true,"sort_order":0,"chat_message":"Quiero información sobre el servicio: ai-generation","cta_message":"Quiero información sobre el servicio: ai-generation","cta_message_en":"I want information about the service: ai-generation","tagline":"De la idea a una pieza con intención","tagline_en":"From an idea to purposeful work","hero_description":"Desarrollamos piezas audiovisuales para marcas, proyectos creativos y comunicación. Elegimos recursos de producción, imagen generativa y montaje según el encargo; la dirección y la revisión de la pieza siguen siendo humanas.","hero_description_en":"We develop audiovisual work for brands, creative projects and communication. Production resources, generative imagery and editing are chosen for the brief; direction and review remain human.","features":[{"title":"Concepto y guion","description":"Definimos la idea, el relato y el formato que necesita el proyecto."},{"title":"Producción de imagen","description":"Combinamos recursos de producción e IA cuando aportan valor a la pieza."},{"title":"Montaje y acabado","description":"Damos forma al ritmo, la imagen y la entrega final acordada."}],"features_en":[{"title":"Concept and script","description":"We define the idea, narrative and format required by the project."},{"title":"Image production","description":"We combine production resources and AI where they add value to the work."},{"title":"Editing and finishing","description":"We shape the rhythm, image and agreed final delivery."}],"process":[{"title":"Brief y referencias","description":"Concretamos el objetivo, el público y el uso de la pieza.","step":"1"},{"title":"Propuesta y producción","description":"Acordamos alcance, recursos y revisiones antes de producir.","step":"2"},{"title":"Revisión y entrega","description":"Revisamos el resultado y preparamos los formatos acordados.","step":"3"}],"process_en":[{"title":"Brief and references","description":"We clarify the objective, audience and intended use.","step":"1"},{"title":"Proposal and production","description":"Scope, resources and revisions are agreed before production.","step":"2"},{"title":"Review and delivery","description":"We review the result and prepare the agreed formats.","step":"3"}],"is_published":false},{"id":"00000000-0000-4000-8000-000000000921","slug":"marketing-strategy","title":"Marketing y estrategia","title_en":"Marketing and strategy","description":"Estrategia de comunicación y contenido alineada con tu marca.","description_en":"Communication and content strategy aligned with your brand.","icon":"campaign","highlighted":false,"sort_order":1,"chat_message":"Quiero información sobre el servicio: marketing-strategy","cta_message":"Quiero información sobre el servicio: marketing-strategy","cta_message_en":"I want information about the service: marketing-strategy","tagline":"Una idea clara antes de producir","tagline_en":"A clear direction before production","hero_description":"Trabajamos la dirección de comunicación de una marca o proyecto: qué contar, a quién y en qué canales. Traducimos los objetivos en una propuesta de contenido y acciones que el equipo pueda llevar a la práctica.","hero_description_en":"We shape the communication direction of a brand or project: what to say, to whom and through which channels. We turn objectives into a content and action proposal that the team can put into practice.","features":[{"title":"Enfoque de marca","description":"Ordenamos el mensaje, el público y la propuesta de comunicación."},{"title":"Estrategia de contenido","description":"Proponemos temas, formatos y canales adecuados al objetivo."},{"title":"Plan de acción","description":"Definimos prioridades y un calendario de trabajo ajustado al alcance."}],"features_en":[{"title":"Brand direction","description":"We clarify the message, audience and communication proposition."},{"title":"Content strategy","description":"We propose themes, formats and channels suited to the objective."},{"title":"Action plan","description":"We define priorities and a work schedule matched to the agreed scope."}],"process":[{"title":"Contexto y objetivos","description":"Revisamos la situación de la marca y lo que quieres conseguir.","step":"1"},{"title":"Propuesta estratégica","description":"Definimos una dirección y las acciones que conviene priorizar.","step":"2"},{"title":"Plan y seguimiento","description":"Acordamos entregables y cómo revisar su aplicación.","step":"3"}],"process_en":[{"title":"Context and objectives","description":"We review the brand context and what you want to achieve.","step":"1"},{"title":"Strategic proposal","description":"We define a direction and the actions to prioritise.","step":"2"},{"title":"Plan and follow-up","description":"We agree deliverables and how to review their application.","step":"3"}],"is_published":false},{"id":"00000000-0000-4000-8000-000000000922","slug":"content-creation","title":"Creación de contenido","title_en":"Content creation","description":"Contenido visual y audiovisual para redes, campañas y comunicación.","description_en":"Visual and audiovisual content for social media, campaigns and communication.","icon":"videocam","highlighted":false,"sort_order":2,"chat_message":"Quiero información sobre el servicio: content-creation","cta_message":"Quiero información sobre el servicio: content-creation","cta_message_en":"I want information about the service: content-creation","tagline":"Contenido con una voz propia","tagline_en":"Content with a distinct voice","hero_description":"Creamos contenido adaptado a la identidad de cada marca y al contexto en el que se publicará. Podemos trabajar piezas individuales o una serie de contenidos, combinando planificación, creación visual y edición.","hero_description_en":"We create content adapted to each brand’s identity and publishing context. We can work on individual pieces or a content series, combining planning, visual creation and editing.","features":[{"title":"Piezas para redes","description":"Desarrollamos vídeos y recursos visuales adaptados al canal."},{"title":"Contenido de campaña","description":"Creamos piezas que mantienen un concepto y una identidad común."},{"title":"Adaptaciones","description":"Preparamos versiones y formatos definidos en el encargo."}],"features_en":[{"title":"Social media pieces","description":"We develop videos and visual assets adapted to the channel."},{"title":"Campaign content","description":"We create pieces with a shared concept and identity."},{"title":"Adaptations","description":"We prepare the versions and formats defined in the brief."}],"process":[{"title":"Objetivo y formatos","description":"Acordamos público, mensaje, canales y volumen de piezas.","step":"1"},{"title":"Creación y revisión","description":"Desarrollamos el contenido con las revisiones acordadas.","step":"2"},{"title":"Entrega organizada","description":"Preparamos los archivos y versiones para su uso.","step":"3"}],"process_en":[{"title":"Objective and formats","description":"We agree audience, message, channels and the number of pieces.","step":"1"},{"title":"Creation and review","description":"We develop the content with the agreed reviews.","step":"2"},{"title":"Organised delivery","description":"We prepare the files and versions for use.","step":"3"}],"is_published":false},{"id":"00000000-0000-4000-8000-000000000923","slug":"direction","title":"Dirección creativa","title_en":"Creative direction","description":"Concepto, narrativa y criterio visual para dar identidad a cada proyecto.","description_en":"Concept, narrative and visual judgment to give each project its identity.","icon":"palette","highlighted":false,"sort_order":3,"chat_message":"Quiero información sobre el servicio: direction","cta_message":"Quiero información sobre el servicio: direction","cta_message_en":"I want information about the service: direction","tagline":"El criterio creativo guía las herramientas","tagline_en":"Creative judgment guides the tools","hero_description":"Definimos la visión de una pieza o campaña y acompañamos su desarrollo. La dirección creativa conecta concepto, narrativa y lenguaje visual para que los recursos de producción y las herramientas de IA respondan a una misma intención.","hero_description_en":"We define the vision of a piece or campaign and guide its development. Creative direction connects concept, narrative and visual language so that production resources and AI tools serve the same intention.","features":[{"title":"Conceptualización","description":"Exploramos ideas y seleccionamos una dirección creativa."},{"title":"Narrativa y referencias","description":"Desarrollamos el relato y una guía de lenguaje visual."},{"title":"Supervisión creativa","description":"Acompañamos las decisiones de producción y revisamos la coherencia de la pieza."}],"features_en":[{"title":"Concept development","description":"We explore ideas and select a creative direction."},{"title":"Narrative and references","description":"We develop the story and a visual-language guide."},{"title":"Creative supervision","description":"We guide production decisions and review the coherence of the work."}],"process":[{"title":"Escucha y exploración","description":"Entendemos el encargo y buscamos referencias relevantes.","step":"1"},{"title":"Dirección propuesta","description":"Presentamos el concepto y el tratamiento creativo.","step":"2"},{"title":"Acompañamiento","description":"Revisamos las decisiones de la pieza dentro del alcance acordado.","step":"3"}],"process_en":[{"title":"Listening and exploration","description":"We understand the brief and look for relevant references.","step":"1"},{"title":"Proposed direction","description":"We present the concept and creative treatment.","step":"2"},{"title":"Guidance","description":"We review decisions within the agreed scope.","step":"3"}],"is_published":false},{"id":"00000000-0000-4000-8000-000000000924","slug":"vfx-post","title":"VFX y postproducción","title_en":"VFX and post-production","description":"Montaje, composición, tratamiento de imagen y acabado audiovisual.","description_en":"Editing, compositing, image treatment and audiovisual finishing.","icon":"layers","highlighted":false,"sort_order":4,"chat_message":"Quiero información sobre el servicio: vfx-post","cta_message":"Quiero información sobre el servicio: vfx-post","cta_message_en":"I want information about the service: vfx-post","tagline":"Dar forma al resultado final","tagline_en":"Shaping the final result","hero_description":"Trabajamos el acabado de material grabado o generado: montaje, composición y tratamiento de imagen. Revisamos primero los recursos y las necesidades técnicas para proponer un alcance viable para cada pieza.","hero_description_en":"We work on the finishing of recorded or generated material: editing, compositing and image treatment. We first review the assets and technical needs to propose a feasible scope for each piece.","features":[{"title":"Montaje","description":"Organizamos el material y desarrollamos el ritmo de la pieza."},{"title":"Composición y efectos","description":"Integramos elementos visuales según las necesidades del proyecto."},{"title":"Imagen y versiones","description":"Ajustamos el acabado visual y preparamos los formatos acordados."}],"features_en":[{"title":"Editing","description":"We organise the material and develop the rhythm of the work."},{"title":"Compositing and effects","description":"We integrate visual elements according to the project’s needs."},{"title":"Image and versions","description":"We refine the visual finish and prepare the agreed formats."}],"process":[{"title":"Revisión de material","description":"Comprobamos los archivos, referencias y requisitos de entrega.","step":"1"},{"title":"Postproducción","description":"Desarrollamos el trabajo y sus revisiones según el alcance.","step":"2"},{"title":"Acabado y exportación","description":"Revisamos la pieza y generamos los archivos de entrega.","step":"3"}],"process_en":[{"title":"Asset review","description":"We check files, references and delivery requirements.","step":"1"},{"title":"Post-production","description":"We develop the work and its reviews within the agreed scope.","step":"2"},{"title":"Finishing and export","description":"We review the piece and generate the delivery files.","step":"3"}],"is_published":false},{"id":"00000000-0000-4000-8000-000000000925","slug":"sound-design","title":"Diseño sonoro","title_en":"Sound design","description":"Edición y diseño de sonido para reforzar la narrativa audiovisual.","description_en":"Sound editing and design to support audiovisual storytelling.","icon":"graphic_eq","highlighted":false,"sort_order":5,"chat_message":"Quiero información sobre el servicio: sound-design","cta_message":"Quiero información sobre el servicio: sound-design","cta_message_en":"I want information about the service: sound-design","tagline":"El sonido también cuenta la historia","tagline_en":"Sound tells the story too","hero_description":"Diseñamos el tratamiento sonoro de una pieza a partir de su narrativa, ritmo y contexto de reproducción. Acordamos los recursos musicales y de sonido, sus derechos de uso y las necesidades de edición antes de comenzar.","hero_description_en":"We design a piece’s sound treatment around its narrative, rhythm and playback context. Music and sound resources, usage rights and editing needs are agreed before work begins.","features":[{"title":"Ambientes y efectos","description":"Construimos una propuesta sonora que acompaña la imagen."},{"title":"Edición de audio","description":"Organizamos y ajustamos los recursos disponibles para la pieza."},{"title":"Integración audiovisual","description":"Revisamos la relación entre sonido, montaje y mensaje."}],"features_en":[{"title":"Ambiences and effects","description":"We build a sound proposal that supports the image."},{"title":"Audio editing","description":"We organise and adjust the available resources for the piece."},{"title":"Audiovisual integration","description":"We review the relationship between sound, editing and message."}],"process":[{"title":"Referencias y recursos","description":"Definimos la intención sonora y revisamos el material disponible.","step":"1"},{"title":"Diseño y edición","description":"Desarrollamos el sonido con las revisiones acordadas.","step":"2"},{"title":"Integración y entrega","description":"Revisamos la pieza completa y entregamos los formatos definidos.","step":"3"}],"process_en":[{"title":"References and assets","description":"We define the sound direction and review available material.","step":"1"},{"title":"Design and editing","description":"We develop the sound with the agreed reviews.","step":"2"},{"title":"Integration and delivery","description":"We review the complete piece and deliver the defined formats.","step":"3"}],"is_published":false}]$akrasia_services$::jsonb) AS draft
